import { build } from "esbuild";
import { mkdir, copyFile, writeFile } from "node:fs/promises";
import countries from "world-countries";
import { searchText } from "../shared/search-text.js";
import { bundleGermanLookup, germanGeography } from "./german-language-data.js";

await mkdir("vendor", { recursive: true });
const segmenter = new Intl.Segmenter("en", { granularity: "word" });
const alias = (value) =>
  [...segmenter.segment(searchText(value))]
    .filter(({ isWordLike }) => isWordLike)
    .map(({ segment }) => segment)
    .join(" ");
// Ship only names/demonyms, not the full geographic dataset or its map assets.
await bundleGermanLookup();
const german = await germanGeography(countries);
const families = countries.map(
  ({ name, demonyms, independent, cca2, translations }) => [
    searchText(name.common),
    Boolean(independent),
    [
      ...new Set(
        [
          name.common,
          name.official,
          translations?.deu?.common,
          translations?.deu?.official,
          ...german.get(cca2).names,
        ].filter(Boolean),
      ),
    ].map(alias),
    [
      ...new Set([
        ...Object.values(demonyms?.eng || {}),
        ...german.get(cca2).people,
      ]),
    ].map(alias),
  ],
);
await writeFile(
  "vendor/country-word-families.js",
  `// Generated from world-countries by npm run build. ODbL: WORLD-COUNTRIES-LICENSE.txt\nexport default ${JSON.stringify(families)};\n`,
);
await build({
  stdin: {
    contents:
      'export { default } from "wink-lemmatizer"; export { default as englishWords } from "wink-lexicon/src/wn-words.js";',
    resolveDir: process.cwd(),
  },
  outfile: "vendor/lemmatizer.js",
  bundle: true,
  format: "esm",
  target: "chrome126",
  minify: true,
  legalComments: "eof",
  banner: { js: "// Generated by npm run build from wink-lemmatizer." },
});
await build({
  stdin: {
    contents: 'export { franc } from "franc-min";',
    resolveDir: process.cwd(),
  },
  outfile: "vendor/language-detector.js",
  bundle: true,
  format: "esm",
  target: "chrome126",
  minify: true,
  legalComments: "eof",
  banner: { js: "// Generated by npm run build from franc-min." },
});
for (const [source, target] of [
  ["world-countries", "WORLD-COUNTRIES"],
  ["wink-lemmatizer", "WINK-LEMMATIZER"],
  ["wink-lexicon", "WINK-LEXICON"],
  ["wink-porter2-stemmer", "WINK-PORTER2-STEMMER"],
])
  await copyFile(
    `node_modules/${source}/LICENSE`,
    `vendor/${target}-LICENSE.txt`,
  );
await copyFile(
  "data/word-language/FRANC-LICENSE.txt",
  "vendor/FRANC-MIN-LICENSE.txt",
);
for (const source of ["trigram-utils", "n-gram", "collapse-white-space"])
  await copyFile(
    `node_modules/${source}/license`,
    `vendor/${source.toUpperCase()}-LICENSE.txt`,
  );
process.exit(0);
